-- users.id=42 のメールアドレス更新
-- :new_email に新しいアドレスを入れて実行する
-- 例: psql "$DATABASE_URL" -v new_email="'new@example.com'" -f fix_user.sql
BEGIN;
SELECT id, email FROM users WHERE id = 42;
UPDATE users SET email = :new_email WHERE id = 42;
SELECT id, email FROM users WHERE id = 42;
COMMIT;
